MultiLanguageSpellData['ru'][1217055] = {name = "Необходимая жертва", additional_info = "Мгновенное действие\n[q]\"Череда побед!\" действует еще 8 сек. после того, как ее отменяет \"Танец клинков\" или \"Удар Хаоса\".\n\n Превращение в демона жертвует все эффекты \"Череды побед!\" и повышает вероятность критического удара на 2% за каждый поглощенный эффект. Действует в течение 15 сек."}
MultiLanguageSpellData['ru'][1217078] = {name = "Череда побед!", additional_info = "Мгновенное действие\n[q]Ваши заклинания и способности с некоторой вероятностью активируют \"Череду побед!\" , увеличивающую урон от \"Устранения\" на 6%. Суммируется до 5 раз. \"Устранение\" с вероятностью 15% прекращает действие \"Череды побед!\" .\n(Вероятность срабатывания: 15%)"}
MultiLanguageSpellData['ru'][1217083] = {name = "Ногоразрыватель", additional_info = "Радиус действия: 300 м\nМгновенное действие\n[q]Всесхватс разбрасывает на поле боя несколько мин. Игрок, наступивший на \"Ногоразрыватель\", активирует \" Нестабильный взрыв \", а в его тело вонзается \" Нестабильная шрапнель \". Кроме того, другие изобретения или \" Проводная передача \" могут взорвать эти высокочувствительные мины, активируя \" Нестабильный взрыв \"."}
