MultiLanguageSpellData['ru'][1218703] = {name = "Неполадка в мастерской", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Хромовый дом испытывает серьезные неполадки, излучая разряды электричества, наносящие пораженным целям 8385087 ед. урона от сил природы раз в 1 сек."}
MultiLanguageSpellData['ru'][1218704] = {name = "Прототип энергокатушки", additional_info = "Радиус действия: 300 м\nНаправляемое (Применение: 10 сек)\n[q]Из свалки появляются экспериментальные энергокатушки.\n\n Энергокатушки образуют связь со случайным игроком и разряжают накопленную энергию, нанося 293478 ед. урона от сил природы и применяя 1 эффект \" Гиперзаряд \" раз в 0.5 сек. в течение 10 сек."}
MultiLanguageSpellData['ru'][1218706] = {name = "Прототип энергокатушки", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Из свалки появляются экспериментальные энергокатушки.\n\n Энергокатушки образуют связь со случайным игроком и разряжают накопленную энергию, нанося 293478 ед. урона от сил природы и применяя 1 эффект \" Гиперзаряд \" раз в 0.5 сек. в течение 10 сек."}
MultiLanguageSpellData['ru'][1218708] = {name = "Гиперзаряд", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]В теле цели накапливается энергия, увеличивающая урон, получаемый от прототипа энергокатушки, на 30% за каждый заряд."}
