MultiLanguageSpellData['ru'][1223254] = {name = "Палец-пистолет штормовой ярости", additional_info = "Радиус действия: 60 м\nМгновенное действие\n[q]Граб выпускает из пальца молнию, нанося игрокам в секторе перед собой 2515526 ед. урона от сил природы раз в 0.5 сек. в течение 4 сек.\n\n Из-за избыточного электричества в области действия образуется \" Туча штормовой ярости \"."}
MultiLanguageSpellData['ru'][1223255] = {name = "Сдвиг", additional_info = "Мгновенное действие\n[q]Адар открывает порталы, которые связывают его с местом, где находится \" Коллапсирующая звезда \", и проходит через них.\n\n Все игроки, которые коснутся порталов, также перенесутся, получат 0 ед. космического урона и эффект \" Звездная вспышка \"."}
