MultiLanguageSpellData['ru'][1225135] = {name = "Ответная реакция", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Зона подавления \" поглощает эффект \" Руническая метка \" на цели и создает залп чародейских стрел. Каждая стрела наносит игрокам в радиусе 3 м от места удара 290947 ед. урона от тайной магии, а также усмиряет их и поражает немотой на 3 сек."}
MultiLanguageSpellData['ru'][1225136] = {name = "Стазисная мина", additional_info = nil}
MultiLanguageSpellData['ru'][1225137] = {name = "Перегрузка изначальной травы", additional_info = "Радиус действия: 5 м\nПрименение: 5.3 сек\n[q]Изначальные травы имеют глубокую связь с Азеротом, благодаря чему опытный травник может через них общаться с самой землей. Перегружая этот вид травы, вы направляете в землю часть своего здоровья, получая взамен частицы изначальной энергии в зависимости от того, сколько предложили.\nDiscovery:\nMidnight Gathering Nodes"}
MultiLanguageSpellData['ru'][1225138] = {name = "Исцеляющий бросок", additional_info = "Мгновенное действие\n[q]Вы осторожно бросаете раненого новобранца. Если бросить раненого новобранца аратийскому жрецу, тот оживит его."}
