MultiLanguageSpellData['ru'][1225928] = {name = "Экспериментальная обшивка", additional_info = "Мгновенное действие\n[q]Ползучая мина покрыта экспериментальной броней, защищающей от урона.\n\n Накопив 100 ед. энергии, мина получает невосприимчивость к эффектам контроля, а ее скорость передвижения повышается на 200%."}
