MultiLanguageSpellData['ru'][1230761] = {name = "[q2]Слиток сверкающей меди", additional_info = "Применение: 2 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nСияющий плавень (2), Сверкающая медная руда (5)\nДополнительные реагенты:\nПочерк ремесленника (#396)\nProfession Trainer:\nMidnight Blacksmithing (1)\nCost:\n50\n\n[q2]Слиток сверкающей меди\nИспользуется для ремесел\n\n[q2]Дает свойство: Слиток сверкающей меди\n[q]\"Выплавляется игроками с навыком кузнечного дела. Можно купить или продать на аукционе.\""}
MultiLanguageSpellData['ru'][1230762] = {name = "[q2]Сумрачный сплав", additional_info = "Применение: 2 сек\nИнструменты: Кузнечный молот\nИнгредиенты:\nСияющий плавень (4), Теневая оловянная руда (6), Слиток сверкающей меди (3)\nДополнительные реагенты:\nПочерк ремесленника (#396)\nProfession Trainer:\nMidnight Blacksmithing (15)\nCost:\n140\n\n[q2]Сумрачный сплав\nИспользуется для ремесел\n\n[q2]Дает свойство: Сумрачный сплав\n[q]\"Выплавляется игроками с навыком кузнечного дела. Можно купить или продать на аукционе.\""}
