MultiLanguageSpellData['ru'][1236160] = {name = "Воспламенение", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]\"Огненный шар\", \"Огненный взрыв\", \"Ожог\", \"Огненная глыба\" [ Метеор : \"Метеорит\" ] [ Пламя феникса : \"Пламя феникса\" ] [ Вихрь углей : \"Вихрь углей\" ] и \"Огненный столб\" воспламеняют цель, нанося ей еще 4.0% от первоначального урона за 9 сек. Если этот эффект обновляется на цели, оставшийся урон от \"Воспламенения\" добавляется к новому.\n\n \"Огненный взрыв\" распространяет эффект \"Воспламенения\" еще на 3 ближайших противников:ближайших противников."}
