MultiLanguageSpellData['ru'][1236330] = {name = "Druid Druid of the Claw 11.2 Class Set 4pc", additional_info = "[q]Сила зверя\n \"Терзание\" с вероятностью 40% поражает цель еще раз через 4 сек. с эффективностью 100% от изначальной.\n\nБаланс, Страж, Исцеление\n \"Терзание\" с вероятностью 40% поражает цель еще раз через 4 сек. с эффективностью 60%."}
MultiLanguageSpellData['ru'][1236331] = {name = "Druid Druid of the Claw 11.2 Class Set 2pc", additional_info = "[q]\"Терзание\" повышает скорость на 10%, вероятность критического удара – на 10%, а также увеличивает урон от эффектов кровотечения на 30% на 5 сек.\n(Восстановление: 100мс)"}
MultiLanguageSpellData['ru'][1236332] = {name = "Druid Elune's Chosen 11.2 Class Set 2pc", additional_info = "[q]Сила зверя, Страж, Исцеление\n Урон от \"Взбучки\" увеличивается на 20%. Когда вы применяете \"Взбучку\", вы с вероятностью 40% поражаете цель \"Звездным потоком\" с эффективностью 160%.\n\nБаланс\n Урон от \"Звездного огня\" увеличивается на 15%. Когда вы накапливаете астральную мощь с помощью \"Звездного огня\", вы с вероятностью 40% поражаете цель \"Звездным потоком\" с эффективностью 45%.\n\n(Восстановление: 100мс)"}
MultiLanguageSpellData['ru'][1236333] = {name = "Druid Elune's Chosen 11.2 Class Set 4pc", additional_info = "[q]Сила зверя, Страж, Исцеление\n Поразив цель, \"Звездные потоки\", примененные \"Взбучкой\", отражаются еще в 3 противников:противников с эффективностью 20% и дают эффект \"Ореол лунного света\". Когда вы применяете \"Лунный луч\", \"Ореол лунного света\" поглощается и наносимый вами урон увеличивается на 4% на 12 сек. за каждый эффект.\n\nБаланс\n Поразив цель, \"Звездные потоки\", примененные \"Звездным огнем\", отражаются еще в 3 противников:противников с эффективностью 40% и дают эффект \"Ореол лунного света\". Когда вы применяете \"Ярость Элуны\" или \"Полную луну\", \"Ореол лунного света\" поглощается и наносимый вами урон увеличивается на 4% на 12 сек. за каждый эффект."}
MultiLanguageSpellData['ru'][1236334] = {name = "Druid Keeper of the Grove 11.2 Class Set 2pc", additional_info = "[q]Исцеление\n Применяя \"Воплощение: древо жизни\" или \"Созыв духов\", вы на 5 сек. призываете на помощь дриаду, которая применяет \"Спокойствие\" с эффективностью 50% и мгновенно применяет к союзнику с самым низким уровнем здоровья \"Восстановление\" с эффективностью 200%.\n\nБаланс, Сила зверя, Страж\n Применяя \"Парад планет\", вы на 10 сек. призываете на помощь дриаду, которая применяет \"Звездный поток\" с эффективностью 360% и \"Звездопад\" с эффективностью 800%."}
MultiLanguageSpellData['ru'][1236336] = {name = "Druid Keeper of the Grove 11.2 Class Set 4pc", additional_info = "[q]Исцеление\n Когда ваша дриада исчезает, 2 следующих \"Быстрых восстановления\" восполняют:следующих \"Быстрых восстановлений\" восполняют дополнительное здоровье в объеме 5% исцеления, примененного вами во время существования дриады. 25% исцеления от этих способностей также применяется к находящимся рядом союзникам. После 5-й цели эффективность снижается.\n\nБаланс, Сила зверя, Страж\n Когда ваша дриада исчезает, 2 следующих \"Звездных потока\" наносят:следующих \"Звездных потоков\" наносят дополнительный урон в объеме 3% урона, нанесенного вами во время существования дриады. 10% урона от этих способностей также наносится ближайшим противникам. После 5-й цели эффективность снижается."}
MultiLanguageSpellData['ru'][1236337] = {name = "Druid Wildstalker 11.2 Class Set 2pc", additional_info = "[q]Сила зверя\n Скорость роста \"Кровососущих лиан\" повышается на 40%. \"Тигриное неистовство\" выращивает \"Кровососущие лианы\" максимум на 3 подходящих ближайших противниках.\n\nБаланс, Страж, Исцеление\n Скорость роста \"Цветов-симбионтов\" повышается на 45%. Когда вы применяете \"Восстановление\" с эффектом \"Ясность мысли\", \"Цветы-симбионты\" вырастают максимум на 2 подходящих союзниках рядом с вами."}
MultiLanguageSpellData['ru'][1236338] = {name = "Druid Wildstalker 11.2 Class Set 4pc", additional_info = "[q]Сила зверя\n \"Кровососущие лианы\" с вероятностью 20% вызывают срабатывание \"Бешеного роста\" раз в 2 сек. с эффективностью 100%. За каждый эффект \"Кровососущие лианы\", действующий на противника, получаемый урон от \"Бешеного роста\" увеличивается на 40%.\n\nБаланс, Страж, Исцеление\n \"Цветы-симбионты\" с вероятностью 35% вызывают срабатывание \"Бешеного роста\" раз в 2 сек. с эффективностью 100%. За каждый эффект \"Цветы-симбионты\", действующий на союзника, получаемое исцеление от \"Бешеного роста\" увеличивается на 30%."}
MultiLanguageSpellData['ru'][1236342] = {name = "Подготовка к удару", additional_info = "Мгновенное действие\n[q]Сила зверя\n\"Терзание\" с вероятностью 40% поражает цель еще раз через 4 сек. с эффективностью 100% от изначальной.\n\nБаланс, Страж, Исцеление\n\"Терзание\" с вероятностью 40% поражает цель еще раз через 4 сек. с эффективностью 60%."}
