MultiLanguageSpellData['ru'][1236386] = {name = "Ободрение союзника", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]Аратор наполняет союзника свежими силами."}
MultiLanguageSpellData['ru'][1236388] = {name = "Защитный барьер", additional_info = "Мгновенное действие\n[q]Барьер защищает это существо."}
MultiLanguageSpellData['ru'][1236389] = {name = "Paladin Lightsmith 11.2 Class Set 2pc", additional_info = "[q]Защита\n Наносимый урон \"Молота и наковальни\" увеличивается на 15%. Теперь также активирует этот эффект с эффективностью 40%.\n\nВоздаяние\n Сила исцеления \"Молота и наковальни\" увеличивается на 15%. Теперь \"Удар воина Света\" также активирует этот эффект с эффективностью 40%.\n\nСвет\n Сила исцеления \"Молота и наковальни\" увеличивается на 15%. Теперь \"Удар воина Света\" также активирует этот эффект с эффективностью 75%.\n\n(Восстановление: 750мс)"}
MultiLanguageSpellData['ru'][1236390] = {name = "Paladin Lightsmith 11.2 Class Set 4pc", additional_info = "[q]\"Молот и наковальня\" также дают эффект \"Высшее мастерство\": следующее \"Священное оружие\" также создает ослабленную версию оружия для одного находящегося рядом союзника за каждый эффект."}
MultiLanguageSpellData['ru'][1236391] = {name = "Paladin Templar 11.2 Class Set 2pc", additional_info = "[q]\"Небесный молот\" наносит на 20% больше критического урона, а его критические удары с вероятностью 50% дают дополнительный эффект \"Избавление Света\".\n(Вероятность срабатывания: 50%)"}
MultiLanguageSpellData['ru'][1236392] = {name = "Paladin Templar 11.2 Class Set 4pc", additional_info = "[q]Воздаяние\n \"Молот Света\" наносит на 35% больше урона основной цели, поражает еще 3 дополнительные цели:дополнительных целей и может быть применен еще 1 раз после \"Испепеляющего следа\".\n\nСвет, Защита\n \"Молот Света\" наносит на 35% больше урона основной цели, поражает еще 3 дополнительные цели:дополнительных целей и может быть применен еще 1 раз после \"Ока Тира\"."}
MultiLanguageSpellData['ru'][1236394] = {name = "Priest Oracle 11.2 Class Set 2pc", additional_info = "[q]Свет, Тьма\n\"Молитва восстановления\" восполняет цели ([1400% of Spell Power]) ед. здоровья.\n\nПослушание\n Урон и сила исцеления от первого снаряда каждой \"Исповеди\" увеличивается на 200%."}
MultiLanguageSpellData['ru'][1236395] = {name = "Priest Oracle 11.2 Class Set 4pc", additional_info = "[q]\"Предчувствие праведности\" и \"Предчувствие покоя\" дают 2 эффекта:эффектов \"Предчувствие прозрения\" с эффективностью 100%. Когда эффект \"Предчувствие прозрения\" поглощается, ваша скорость повышается на 1.0% на 10 сек. Эффекты могут накладываться друг на друга."}
MultiLanguageSpellData['ru'][1236396] = {name = "Priest Voidweaver 11.2 Class Set 2pc", additional_info = "[q]Послушание\n Урон от \"Вспышки Бездны\" и \"Исповеди\" увеличивается на 30%, а время применения \"Вспышки Бездны\" сокращается на 20%.\n\nСвет\n Урон от \"Вспышки Бездны\" увеличивается на 30%, а время применения \"Вспышки Бездны\" сокращается на 20%.\n\nТьма\n Урон от \"Вспышки Бездны\" увеличивается на 30%, а время применения \"Вспышки Бездны\" сокращается на 20%. Время восстановления \"Вспышки Бездны\" сокращается на 50%."}
MultiLanguageSpellData['ru'][1236397] = {name = "Priest Voidweaver 11.2 Class Set 4pc", additional_info = "[q]Послушание\n \"Вспышка Бездны\" теперь также увеличивает размер \"Энтропического разлома\", \"Прорывающаяся Бездна\" увеличивает урон от \"Энтропического разлома\" еще на 10%, а урон от следующего \"Взрыва разума\" увеличивается максимум на 200% в зависимости от размера \"Энтропического разлома\" на момент его коллапса.\n\nСвет, Тьма\n \"Вспышка Бездны\" теперь также увеличивает размер \"Энтропического разлома\", \"Прорывающаяся Бездна\" увеличивает урон от \"Энтропического разлома\" еще на 10%, а урон от следующего \"Потока Бездны\" увеличивается максимум на 200% в зависимости от размера \"Энтропического разлома\" на момент его коллапса."}
MultiLanguageSpellData['ru'][1236398] = {name = "Priest Archon 11.2 Class Set 2pc", additional_info = "[q]Тьма\n \"Сияние\" дает еще 10 ед. безумия за 5 сек., а \"Резонирующая энергия\" дополнительно увеличивает урон от \"Всепожирающей чумы\" на 5.0%.\n\nПослушание, Свет\n \"Сияние\" сокращает время восстановления \"Слова Света: Безмятежность\" и \"Слова Света: Освящение\" на 5 сек., а \"Резонирующая энергия\" дополнительно повышает эффективность исцеления \"Слов Света\" на 5.0%."}
MultiLanguageSpellData['ru'][1236399] = {name = "Priest Archon 11.2 Class Set 4pc", additional_info = "[q]Послушание, Тьма\n Пока действует \"Выброс энергии\", каждое 2-е применение \"Всепожирающей чумы\" добавляет еще один эффект \"Сияние\" с эффективностью 100%. Срабатывает до 2 раз.\n\nСвет\n Пока действует \"Выброс энергии\", каждое 2-е применение \"Слова Света: Безмятежность\" или \"Слова Света: Освящение\" добавляет еще один эффект \"Сияние\" с эффективностью 100%. Срабатывает до 2 раз."}
MultiLanguageSpellData['ru'][1236400] = {name = "Rogue Deathstalker 11.2 Class Set 2pc", additional_info = "[q]Ликвидация\n Пока действует \"Отравляющий укол\", эффективность наносящих урон эффектов и прибавок к урону \"Ловчего смерти\" повышается на 60%.\n\nГоловорез, Скрытность\n Пока действуют \"Символы смерти\", эффективность наносящих урон эффектов и прибавок к урону \"Ловчего смерти\" повышается на 40%."}
MultiLanguageSpellData['ru'][1236401] = {name = "Rogue Deathstalker 11.2 Class Set 4pc", additional_info = "[q]Ликвидация\n \"Отравляющий укол\" действует на 3 сек. дольше. При активации способность поглощает эффект действующей \"Метки ловчего смерти\".\n\nГоловорез, Скрытность\n \"Символы смерти\" действуют на 3 сек. дольше. При активации способность поглощает эффект действующей \"Метки ловчего смерти\"."}
MultiLanguageSpellData['ru'][1236402] = {name = "Rogue Fatebound 11.2 Class Set 2pc", additional_info = "[q]Ликвидация, Скрытность\n \"Погибель королей\" наносит на 10% больше урона и действует на 4 сек. дольше.\n\n Когда срабатывает \"Крайний случай\", вы подбрасываете дополнительную \"Судьбоносную монету\". \"Погибель королей\" теперь вызывает срабатывание \"Крайнего случая\".\n\nГоловорез\n \"Призрачный удар\" наносит на 50% больше урона и действует на 4 сек. дольше.\n\n Когда срабатывает \"Крайний случай\", вы подбрасываете дополнительную \"Судьбоносную монету\". \"Призрачный удар\" теперь вызывает срабатывание \"Крайнего случая\"."}
MultiLanguageSpellData['ru'][1236403] = {name = "Rogue Fatebound 11.2 Class Set 4pc", additional_info = "[q]Головорез\n Пока на вас действует счастливая \"Судьбоносная монета\", время восстановления \"Выброса адреналина\" сокращается на 30.0 сек., а \"Призрачного удара\" – на 15.0 сек.\n\nЛиквидация, Скрытность\n Пока на вас действует счастливая \"Судьбоносная монета\", время восстановления \"Знака смерти\" сокращается на 30.0 сек., а \"Погибели королей\" – на 15.0 сек."}
MultiLanguageSpellData['ru'][1236404] = {name = "Rogue Trickster 11.2 Class Set 2pc", additional_info = "[q]\"Незримый клинок\" наносит на 35% больше урона и с вероятностью 35% поражает цель дважды."}
MultiLanguageSpellData['ru'][1236405] = {name = "Rogue Trickster 11.2 Class Set 4pc", additional_info = "[q]\"Удар милосердия\" теперь можно активировать еще раз в течение 5 сек., нанеся 150% обычного урона."}
MultiLanguageSpellData['ru'][1236406] = {name = "Shaman Farseer 11.2 Class Set 2pc", additional_info = "[q]\"Стремительность предков\" на 15 сек. призывает усиленного предка, который наносит на 10% больше урона и восполняет на 10% больше здоровья."}
MultiLanguageSpellData['ru'][1236407] = {name = "Shaman Farseer 11.2 Class Set 4pc", additional_info = "[q]Исцеление\n \"Стремительность предков\" увеличивает урон и силу исцеления заклинаний на 25%, снижает затраты маны на применение заклинаний на 25% и ускоряет восстановление \"Выброса лавы\" и \"Быстрины\" на 50% на 8 сек.\n\nСтихии, Совершенствование\n \"Стремительность предков\" увеличивает урон и силу исцеления заклинаний на 25%, снижает затраты маны на применение заклинаний на 25% и ускоряет восстановление \"Выброса лавы\" на 50% на 8 сек."}
MultiLanguageSpellData['ru'][1236408] = {name = "Shaman Stormbringer 11.2 Class Set 2pc", additional_info = "[q]Совершенствование, Исцеление\n \"Перерождение\" с вероятностью 100% дает заряд \"Бури\". Каждое 8-е \"Пробуждение бурь\" теперь активирует \"Перерождение\" на 6.0 сек.\n\nСтихии\n \"Перерождение\" с вероятностью 100% дает заряд \"Бури\". Каждое 9-е \"Пробуждение бурь\" теперь активирует \"Перерождение\" на 6.0 сек.\n\n(Восстановление: 100мс)"}
MultiLanguageSpellData['ru'][1236409] = {name = "Shaman Stormbringer 11.2 Class Set 4pc", additional_info = "[q]Стихии, Исцеление\n Урон от сил природы увеличивается на 3.0%. \"Перерождение\" усиливает 2 следующие \"Бури\":следующих \"Бурь\", в результате чего они создают грозовые тучи, наносящие ([960% of Spell Power]) ед. урона от сил природы основной цели, а также уменьшенный урон ближайшим противникам спустя 1.5 сек.\n\nСовершенствование\n Урон от сил природы увеличивается на 5.0%. \"Перерождение\" усиливает 2 следующие \"Бури\":следующих \"Бурь\", в результате чего они создают грозовые тучи, наносящие ([400% of Attack Power]) ед. урона от сил природы основной цели, а также уменьшенный урон ближайшим противникам спустя 1.5 сек.\n\n(Восстановление: 100мс)"}
MultiLanguageSpellData['ru'][1236410] = {name = "Shaman Totemic 11.2 Class Set 2pc", additional_info = "[q]Совершенствование\n Когда вы поглощаете все частицы \"Бушующих стихий\", ваш пульсирующий тотем применяет \"Первозданную бурю\" с эффективностью 200% рядом с собой.\n\nСтихии, Исцеление\n Когда вы поглощаете все частицы \"Бушующих стихий\", вы применяете \"Ливневый дождь\" с эффективностью 200% рядом с вашим пульсирующим тотемом."}
MultiLanguageSpellData['ru'][1236411] = {name = "Shaman Totemic 11.2 Class Set 4pc", additional_info = "[q]Стихии, Исцеление\n После того как вы применяете \"Ливневый дождь\", следующее \"Цепное исцеление\", \"Волна исцеления\" или \"Исцеляющий всплеск\" применяется повторно с эффективностью 150%.\n\nСовершенствование\n После того как вы применяете \"Первозданную бурю\", следующее \"Вскипание лавы\" или \"Кольцо огня\" применяется повторно с эффективностью 150%.\n\n(Восстановление: 500мс)"}
