MultiLanguageSpellData['ru'][1236413] = {name = "Warlock Hellcaller 11.2 Class Set 2pc", additional_info = "[q]Демонология, Разрушение\n \"Знак Ксавия\" увеличивает урон от \"Почерневшей души\" еще на 3% за каждый эффект. \"Зловредность\" увеличивает количество эффектов \"Усыхания\" еще на 2.\n\nКолдовство\n \"Знак Ксавия\" увеличивает урон от \"Почерневшей души\" еще на 6% за каждый эффект. \"Зловредность\" увеличивает количество эффектов \"Усыхания\" еще на 2."}
MultiLanguageSpellData['ru'][1236414] = {name = "Warlock Hellcaller 11.2 Class Set 4pc", additional_info = "[q]Колдовство\n При применении \"Зловредность\" дает 2 эффекта:эффектов \"Бедственное крещендо\". При этом \"Почерневшая душа\" не поглощает эффекты и наносит урон на 25% быстрее. Время действия – 8 сек.\n\nДемонология, Разрушение\n При применении \"Зловредность\" дает 2 эффекта:эффектов \"Обратный поток\". При этом \"Почерневшая душа\" не поглощает эффекты и наносит урон на 15% быстрее. Время действия – 8 сек."}
MultiLanguageSpellData['ru'][1236415] = {name = "Warlock Soul Harvester 11.2 Class Set 2pc", additional_info = "[q]\"Тень смерти\" высвобождает вашу душу демона, и она терзает текущую цель в течение 9 сек. Каждый удар наносит ([279.306% of Spell Power]) ед. урона от темной магии цели и ([186.209% of Spell Power]) ед. урона от темной магии противникам в радиусе 10 м."}
MultiLanguageSpellData['ru'][1236416] = {name = "Warlock Soul Harvester 11.2 Class Set 4pc", additional_info = "[q]Урон от \"Души демона\" увеличивается на 45%, а урон от \"Жестокой жатвы\" – на 45%. Пока душа демона терзает противников, вы накапливаете 1 осколок души в 3 сек."}
MultiLanguageSpellData['ru'][1236417] = {name = "Warlock Diabolist 11.2 Class Set 2pc", additional_info = "[q]Колдовство, Разрушение\n \"Стрела Хаоса\", \"Огненный ливень\" и \"Ожог Тьмы\" призывают демонический окуляр. Максимальное количество окуляров – 3. Когда поглощается эффект \"Демоническое искусство\", демонические окуляры устремляются к текущей цели и взрываются, нанося ([502.813% of Spell Power]) ед. урона от огня ей и ([335.172% of Spell Power]) ед. урона от огня противникам в радиусе 10 м.\n\nДемонология\n Примененная с максимальной силой \"Рука Гул'дана\" призывает демонический окуляр. Максимальное количество окуляров – 3. Когда поглощается эффект \"Демоническое искусство\", демонические окуляры устремляются к текущей цели и взрываются, нанося ([502.813% of Spell Power]) ед. урона от огня ей и ([335.172% of Spell Power]) ед. урона от огня противникам в радиусе 10 м."}
MultiLanguageSpellData['ru'][1236418] = {name = "Warlock Diabolist 11.2 Class Set 4pc", additional_info = "[q]Демонические окуляры анализируют ход боя, пока действуют, а затем взрываются и передают информацию, повышая ваш интеллект на 2% на 10 сек."}
MultiLanguageSpellData['ru'][1236419] = {name = "Warrior Colossus 11.2 Class Set 2pc", additional_info = "[q]Урон от \"Разрушения\" увеличивается на 20%, а критический урон от ваших способностей увеличивается максимум на 20% против целей под действием вашего \"Разрушения\". Время действия – 10 сек. Сила эффекта зависит от количества поглощенных эффектов \"Колоссальная мощь\"."}
MultiLanguageSpellData['ru'][1236420] = {name = "Warrior Colossus 11.2 Class Set 4pc", additional_info = "[q]Неистовство, Защита\n \"Разрушение\" повышает вероятность критического удара 1 следующего \"Мощного удара щитом\" на 100%. Критические удары \"Мощного удара щитом\" увеличивают урон от \"Кровопускания\" и \"Глубоких ран\" на 80% на 8 сек.\n\nОружие\n \"Разрушение\" повышает вероятность критического удара 1 следующего \"Смертельного удара\" на 100%. Критические удары \"Смертельного удара\" увеличивают урон от \"Кровопускания\" и \"Глубоких ран\" на 80% на 8 сек."}
MultiLanguageSpellData['ru'][1236421] = {name = "Warrior Mountain Thane 11.2 Class Set 2pc", additional_info = "[q]\"Разряд грома\" с вероятностью 35% обрушивает на пораженные цели 5 \"Ионизирующих удара\":\"Ионизирующих ударов\". Каждый удар наносит ([150% of Attack Power]) ед. урона от сил природы."}
MultiLanguageSpellData['ru'][1236422] = {name = "Warrior Mountain Thane 11.2 Class Set 4pc", additional_info = "[q]\"Ионизирующие удары\" наносят на 100% больше урона. Когда срабатывают \"Ионизирующие удары\", вы получаете заряд \"Разряда грома\" и следующий \"Разряд грома\" наносит на 100% больше урона."}
MultiLanguageSpellData['ru'][1236423] = {name = "Warrior Slayer 11.2 Class Set 2pc", additional_info = "[q]Урон от \"Казни\" увеличивается на 10%. \"Казни\", активированные \"Внезапной смертью\", с вероятностью 10% за каждый эффект \"Сокрушение\" на цели вызывают срабатывание \"Удара палача\" с эффективностью 100%."}
MultiLanguageSpellData['ru'][1236424] = {name = "Warrior Slayer 11.2 Class Set 4pc", additional_info = "[q]Оружие\n Урон от \"Превосходства\" увеличивается на 10%. \"Превосходство\" с вероятностью 2% за каждый действующий на цель эффект \"Сокрушение\" активирует талант \"Пожиная бурю\" с эффективностью 150%.\n\nНеистовство, Защита\n Урон от \"Яростного выпада\" увеличивается на 10%. \"Яростный выпад\" с вероятностью 2% за каждый действующий на цель эффект \"Сокрушение\" активирует талант \"Пожиная бурю\" с эффективностью 150%.\n\n(Восстановление: 500мс)"}
