MultiLanguageSpellData['ru'][1236957] = {name = "Ослабляющий удар", additional_info = "Радиус действия: 15 м\n{Применение: 2 сек} {Восстановление: 5 сек}\n[q]Встает на дыбы, а затем сокрушает текущую цель, нанося физический урон и ослабляя получаемое исцеление на 10% на 15 сек."}
MultiLanguageSpellData['ru'][1236958] = {name = "Разъедающий сок", additional_info = "Радиус действия: 150 м\nМгновенное действие\n[q]Желудочный сок обжигает цели в области действия, нанося 12 ед. урона от темной магии раз в 1.5 сек. и снижая скорость передвижения на 50%."}
