MultiLanguageSpellData['ru'][1243174] = {name = "Благословение: аура победителя", additional_info = "[q]Акил'зон, лоа победы\n Мот'амра, лоа мора\n\n Благословение лоа победы и лоа мора позволяет вам с вероятностью 15% оглушить противника на 3 сек.\n\n Не действует на игроков.\n Действует только в Зул'Амане."}
MultiLanguageSpellData['ru'][1243175] = {name = "Благословение: шерсторгаши победы", additional_info = "[q]Акил'зон, лоа победы\n Уила'ма, лоа путников\n\n Лоа победы и лоа путников рассылают торговцев, услугами которых вы можете воспользоваться.\n\n Действует только в Зул'Амане."}
MultiLanguageSpellData['ru'][1243176] = {name = "Благословение: победа через уловки", additional_info = "[q]Акил'зон, лоа победы\n Шадра, лоа уловок\n\n Во время боя лоа победы и лоа уловок повышают вашу скорость на 1% раз в сек. Максимум – 15%. Бонус постепенно уменьшается вне боя.\n\n Действует только в Зул'Амане."}
MultiLanguageSpellData['ru'][1243177] = {name = "Благословение: прилив изобилия", additional_info = "[q]Акил'зон, лоа победы\n Дандан, лоа изобилия\n\n Лоа победы и лоа изобилия значительно ускоряют сбор ресурсов и изготовление предметов, повышая сноровку на 15, а скорость изготовления – на 50.\n\n Действует только в Зул'Амане."}
MultiLanguageSpellData['ru'][1243178] = {name = "Благословение: победа любой ценой", additional_info = "[q]Акил'зон, лоа победы\n Пул, лоа опасностей\n\n Когда вы убиваете противника, лоа победы и лоа опасностей повышают вашу скорость передвижения на 100% на 3 сек.\n\n При этом получаемый от следующего источника урон увеличивается на 100%.\n\n Действует только в Зул'Амане."}
MultiLanguageSpellData['ru'][1243179] = {name = "Благословение: победный рост", additional_info = "[q]Акил'зон, лоа победы\n Оэ, лоа роста\n\n Лоа победы и лоа лесов повышают вашу скорость атаки оружием на 25%.\n\n Действует только в Зул'Амане."}
MultiLanguageSpellData['ru'][1243184] = {name = "Благословение: бесконечная охота", additional_info = "[q]Халаззи, лоа охоты\n Кулзи, лоа исцеления\n\n Когда вы убиваете противника, лоа охоты и лоа исцеления восполняют вам 5% здоровья.\n\n Действует только в Зул'Амане."}
MultiLanguageSpellData['ru'][1243185] = {name = "Благословение: охота за простотой", additional_info = "[q]Халаззи, лоа охоты\n Фило, лоа детей\n\n При каждой атаке вы с вероятностью 5% получаете следующий эффект:\n\nМиг простоты :\nЛоа охоты и лоа детей повышают силу заклинаний, силу атаки в ближнем и дальнем бою и силу исцеления на 100% на 3 сек.\n\n Действует только в Зул'Амане."}
MultiLanguageSpellData['ru'][1243186] = {name = "Благословение: преданная адаптация", additional_info = "[q]Халаззи, лоа охоты\n Пак, лоа глубин\n\n Лоа охоты и лоа глубин позволяют задерживать дыхание под водой на 300% дольше.\n\n Действует только в Зул'Амане."}
