MultiLanguageSpellData['ru'][1244008] = {name = "Хаотичные врата Пустоты", additional_info = "Неограниченное расстояние\n{Мгновенное действие} {Восстановление: 2 мин}\n[q]Вы открываете врата Пустоты и заполняете область вокруг оскверненной маной, наносящей противникам 1158 ед. урона раз в 1 сек. в течение 10 сек. Вы восполняете 169 ед. здоровья за каждую пораженную цель вплоть до 8 целей."}
