MultiLanguageSpellData['ru'][1244291] = {name = "Бездна", additional_info = "Радиус действия: 30 м\nМгновенное действие\n[q]Призывает существо Бездны, помогающее вам в бою в течение 30 сек.\n\n Этот эффект усиливается символом Новолуния \"Бездна\" и имеет общее с ним время восстановления."}
