MultiLanguageSpellData['ru'][1245358] = {name = "Заоблачный грифон верховного шамана", additional_info = "Применение: 1.5 сек\n[q]Позволяет призывать и отпускать этот транспорт.\n[q]\"Когда древние шаманы Громового Молота впервые увидели заоблачных грифонов, то приняли их за духов стихий в смертном обличье. Эта встреча так поразила дворфов, что их потомки до сих пор ее вспоминают.\"\nТорговая лавка"}
MultiLanguageSpellData['ru'][1245359] = {name = "Пеплоперый грифон нагорья", additional_info = "Применение: 1.5 сек\n[q]Позволяет призывать и отпускать этот транспорт.\n[q]\"Согласно легендам Громового Молота, эти грифоны унаследовали свои оранжевые перья от предков-элементалей.\"\nТорговая лавка"}
