MultiLanguageSpellData['ru'][1248134] = {name = "Темная звезда", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Из Круговерти Пустоты является звезда, которая затягивает игроков в течение 5 сек.\n\n Если \" Темная звезда \" втягивает игрока, он подвергается эффекту \" Атомизация \", а наружу пробиваются \" Сумеречные шипы \". \"Темная звезда\" наносит 56215 ед. космического урона всем игрокам раз в 1 сек."}
