MultiLanguageSpellData['ru'][1250561] = {name = "Коварный крюк Зацапа", additional_info = "Восстановление: 1.5 мин\n[q]Вы бросаете в цель огромный крюк, пробивающий противников на своем пути и наносящий им физический урон. Врезаясь в землю, крюк наносит Y физического урона, распределяемого между ближайшими противниками."}
