MultiLanguageSpellData['ru'][1250563] = {name = "Боевой штандарт Кролука", additional_info = "Срабатывает приблизительно 4 раз(а) в минуту\n[q]Атаки ближнего боя с некоторой вероятностью призывают элитного метателя топоров, который бросает в вашу цель топор, наносящий ( 1 * 11446 ) ед. физического урона."}
MultiLanguageSpellData['ru'][1250564] = {name = "Последний рык Затуукса", additional_info = "Срабатывает приблизительно 1 раз(а) в минуту\n[q]Наносящие урон способности могут призвать эхо яростного рыка Затуукса, повышающее вашу вероятность критического удара на 104 на 30 сек.\n\n Пока действует этот эффект, каждая ваша атака повышает вероятность критического урона еще на 14 . Эффект суммируется до 5 раз.\n(Восстановление: 30с)"}
MultiLanguageSpellData['ru'][1250565] = {name = "Касание ангела", additional_info = "[q]Критические эффекты исцеляющих заклинаний усиливают исцеление на 220% вместо обычных 200%."}
MultiLanguageSpellData['ru'][1250566] = {name = "Удар порыва ветра", additional_info = "[q]Когда вы поглощаете эффект \"Нокаутирующий удар!\", \"Удар восходящего солнца\" с вероятностью 60% превращается в \"Удар порыва ветра\".\n\nУдар порыва ветра :\nВы создаете порыв ветра, наносящий ([179.75% of Attack Power]) ед. урона от сил природы, распределяемого между противниками в секторе 25 м перед вами. Урон увеличивается на 6% за каждую пораженную цель вплоть до 30%.\n\n [ Ткач туманов : Восполняет ([500% of Spell Power]) ед. здоровья максимум 5 союзникам, на которых действуют ваши эффекты периодического исцеления ]"}
MultiLanguageSpellData['ru'][1250567] = {name = "Ярость Налоракка", additional_info = "Срабатывает приблизительно 2.5 раз(а) в минуту\n[q]Вы доказали свою силу перед Налоракком. Ваши способности с некоторой вероятностью вызывают отголосок яростного рева бога войны, в результате чего ваша сила повышается на 152 на 15 сек.\n\n Также воодушевляет находящихся рядом союзников, заслуживших дары Налоракка, повышая их скорость передвижения на 25% на 10 сек."}
