MultiLanguageSpellData['ru'][1251255] = {name = "Вершинный орел Крутогорья", additional_info = "Применение: 1.5 сек\n[q]Позволяет призывать и отпускать этот транспорт.\n[q]\"Этот величавый орел – символ гордости племен Крутогорья. Способность этих птиц носить на спине могучих тауренов прекрасно демонстрирует, какие огромные и сильные звери обитают в этих краях.\"\nСобытие:\nWoW Remix: Legion"}
