MultiLanguageSpellData['ru'][1251902] = {name = "Печатка азеротских благословений", additional_info = "Срабатывает приблизительно 2 раз(а) в минуту\n[q]Заклинания и способности могут вызвать резонанс печатки с душой мира, повышая второстепенные характеристики на 21 на 15 сек.\n\n Каждый уникальный цвет среди вставленных самоцветов увеличивает прибавку к связанной с ним второстепенной характеристике на 1%."}
