MultiLanguageSpellData['ru'][1253104] = {name = "Рассветный барьер", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]В самые отчаянные мгновения \" Кристалл зари \" излучает Свет, в течение короткого времени позволяя держащему его игроку применить эффект \" Рассветный барьер \".\n\n Кристалл создает яркий мозаичный купол, уменьшающий получаемый игроками урон на 99% в течение максимум 6 сек. При этом \" Кристалл зари \" поглощается."}
MultiLanguageSpellData['ru'][1253110] = {name = "Лапа иссохшего фитоящера", additional_info = "Срабатывает приблизительно 2 раз(а) в минуту\n[q]Критические удары могут пробудить энергию Бездны, повышающую силу или ловкость на 194 на 10 сек."}
MultiLanguageSpellData['ru'][1253111] = {name = "Потерянный идол хаш'эй", additional_info = "Срабатывает приблизительно 1 раз(а) в минуту\n[q]Атаки и способности с низкой вероятностью призывают на помощь случайного лоа, усиливающего вас на 30 сек.\n(Восстановление: 5с)"}
MultiLanguageSpellData['ru'][1253112] = {name = "Лесной вакрапуку", additional_info = "Срабатывает приблизительно 2 раз(а) в минуту\n[q]Наносящие урон заклинания и способности дальнего боя могут призвать аспекты лоа, которые обстреливают цель три раза. Каждая атака лоа наносит ( 1 * 4449 ) ед. физического урона, распределяемого между ближайшими противниками."}
MultiLanguageSpellData['ru'][1253113] = {name = "Манускрипт жнеца Бездны", additional_info = "Срабатывает приблизительно 3 раз(а) в минуту\n[q]Наносящие урон заклинания и способности могут заклеймить цель словами из священного писания, нанося ( 318 * 30) ед. урона от светлой магии за 30 сек.\n\n Когда вы повторно клеймите цель, священный текст вспыхивает, повышая вашу вероятность критического удара на 65 на 15 сек. и мгновенно нанося оставшийся урон.\n(Восстановление: 5с)"}
MultiLanguageSpellData['ru'][1253114] = {name = "Вечноколлапсирующий разлом Бездны", additional_info = "{Мгновенное действие} {Восстановление: 2 мин}\n[q]Вы удерживаете разлом открытым, вызывая искажение времени. При этом ваша скорость передвижения снижается на 50%, но показатель скорости повышается на 80 раз в сек. в течение 10 сек."}
MultiLanguageSpellData['ru'][1253115] = {name = "Запечатанная урна хаоса", additional_info = "{Мгновенное действие} {Восстановление: 2 мин}\n[q]Вы распечатываете урну и выпускаете энергию Бездны, которая окутывает вас и повышает второстепенные характеристики на 133 на 20 сек.\n\n Если вы не убьете ни одного противника за время действия эффекта, вы придете в ужас на 5 сек., когда энергия Бездны рассеется."}
MultiLanguageSpellData['ru'][1253116] = {name = "Дар Света", additional_info = "Срабатывает приблизительно 2 раз(а) в минуту\n[q]Исцеляющие заклинания и способности с некоторой вероятностью повышают искусность на 241 на 10 сек.\n Если эффект срабатывает при исцелении союзника, уровень здоровья которого ниже 40%, бонус к искусности удваивается.\n\n Срабатывает не чаще раза в 1 мин."}
MultiLanguageSpellData['ru'][1253117] = {name = "Освященная чаша", additional_info = "Срабатывает приблизительно 5 раз(а) в минуту\n[q]Исцеляющие заклинания и способности с высокой вероятностью добавляют в чашу каплю надежды. Суммируется до 15 раз."}
MultiLanguageSpellData['ru'][1253118] = {name = "Оскверненная чаша", additional_info = "Срабатывает приблизительно 5 раз(а) в минуту\n[q]Получая урон, вы с высокой вероятностью добавляете в чашу каплю отчаяния. Суммируется до 10 раз. Когда чаша заполняется, отчаяние изливается, создавая вокруг вас темную трясину, которая повышает вашу универсальность на 341 и раз в секунду распределяет между противниками 2741 ед. урона от энергии Бездны. Время действия – 10 сек.\n(Восстановление: 1с)"}
MultiLanguageSpellData['ru'][1253119] = {name = "Приказ святого воздаятеля", additional_info = "Срабатывает приблизительно 2 раз(а) в минуту\n[q]Свет благословляет ваше оружие, в результате чего ваши атаки могут нанести еще 2368 ед. урона от светлой магии и восполнить вам 21787 ед. здоровья."}
MultiLanguageSpellData['ru'][1253120] = {name = "Талисман прославленного рыцаря", additional_info = "Срабатывает приблизительно 2 раз(а) в минуту\n[q]Во время боя вас может охватить фанатичное воодушевление, повышающее наивысшую второстепенную характеристику на 173 на 15 сек.\n\n Также повышает наименьшую второстепенную характеристику участников группы, у которых есть такой же талисман, на 17 на 15 сек."}
MultiLanguageSpellData['ru'][1253121] = {name = "Споровыпускатель", additional_info = "Мгновенное действие\n[q]Вас на [B] сек. окружает щит из спор, поглощающий [A] ед. урона. По завершении действия щита ваше самоисцеление усиливается на [C] на [D] сек."}
MultiLanguageSpellData['ru'][1253122] = {name = "Гри-гри уверенности", additional_info = "Мгновенное действие\n[q]Вы уверены, что можете предугадывать движения оппонентов, в результате чего ваше самоисцеление усиливается на [A]. Когда вы получаете урон, ваше самоисцеление может снизиться на [B] вплоть до [C]. Когда вы убиваете противника, самоисцеление возвращается на прежний уровень."}
MultiLanguageSpellData['ru'][1253129] = {name = "Гнедой скакун", additional_info = "Применение: 1.5 сек\n[q]Позволяет призывать и отпускать этот транспорт.\n[q]\"Из этих животных получаются отличные скакуны. Главное, не спешиваться со стороны головы.\"\nСобытие:\nWoW Remix: Legion"}
MultiLanguageSpellData['ru'][1253130] = {name = "Серный скакун", additional_info = "Применение: 1.5 сек\n[q]Позволяет призывать и отпускать этот транспорт.\n[q]\"По цвету пламени на копытах скакуна можно определить, с какой школой магии он связан.\"\nСобытие:\nWoW Remix: Legion"}
