MultiLanguageSpellData['ru'][1265012] = {name = "Взрывная рана", additional_info = "Радиус действия: 100 м\nМгновенное действие\n[q]\" Взрывная рана \", оставленная ножом Джин'Ма, наносит 2314 ед. урона от темной магии цели и другим игрокам в радиусе 8 м. Если рядом находится \" Освежеванный дух \", он также получает урон. Время действия – 6 сек."}
