MultiLanguageSpellData['ru'][1265016] = {name = "Исторжение паразита", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Ненасытникус сбрасывает с себя огнежальщиков-паразитов и разбрызгивает по полю боя сгустки темного гноя, наносящие игрокам в радиусе 3 м от мест ударов 338133 ед. урона от темной магии."}
