MultiLanguageSpellData['ru'][1265780] = {name = "Эдикт священной обители", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Во время боя, а также при убийстве противников ваш спутник может получить благословение священной обители. Убийство элитного противника дает 5 эффекта:эффектов \"Благословение священной обители\", а убийство обычного противника – 1 эффект.\n\n Каждый эффект благословения увеличивает наносимый урон и силу исцеления на 1%. Когда спутник накапливает 15 эффекта:эффектов, 30% его текущего запаса здоровья преобразуется в поглощающий урон щит, – и пока этот щит действует, он увеличивает бонусы к урону и силе исцеления от \"Благословения священной обители\"."}
MultiLanguageSpellData['ru'][1265781] = {name = "Указ Света", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Бело'рен яростно атакует цели в секторе перед собой, нанося 2415233 ед. урона от светлой магии и 966093 ед. физического урона, а также отбрасывая их."}
MultiLanguageSpellData['ru'][1265782] = {name = "Покинуть место проведения ритуала", additional_info = nil}
MultiLanguageSpellData['ru'][1265783] = {name = "Эдикт священной обители: убийство", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Во время боя, а также при убийстве противников ваш спутник может получить благословение священной обители. Убийство элитного противника дает 5 эффекта:эффектов \"Благословение священной обители\", а убийство обычного противника – 1 эффект.\n\n Каждый эффект благословения увеличивает наносимый урон и силу исцеления на 1%. Когда спутник накапливает 15 эффекта:эффектов, 30% его текущего запаса здоровья преобразуется в поглощающий урон щит, – и пока этот щит действует, он увеличивает бонусы к урону и силе исцеления от \"Благословения священной обители\"."}
MultiLanguageSpellData['ru'][1265784] = {name = "Светоносный крылобег", additional_info = "Применение: 1.5 сек\n[q]Позволяет призывать и отпускать этот транспорт.\n[q]\"Верный зверь талассийских аристократов. Уютнее всего ему в каком-нибудь укромном уголке террасы Магистров.\"\nИсточник:\nДегентрий\nЗона:\nтерраса Магистров (эпохальный режим)\n\nИсточник:\nтайник претендента\nЗона:\nтерраса Магистров"}
MultiLanguageSpellData['ru'][1265785] = {name = "Изумрудный крылобег", additional_info = "Применение: 1.5 сек\n[q]Позволяет призывать и отпускать этот транспорт.\n[q]\"Всадник погиб в бою, так что седло достается вам.\"\nЗадание:\n\"Битва у моста\"\nЗона:\nЛуносвет"}
MultiLanguageSpellData['ru'][1265786] = {name = "Талассийская отмычка", additional_info = "Радиус действия: 5 м\nПрименение: 5 сек\n[q]Позволяет отпирать замки, требующие навык вскрытия замков не более 90. Эта отмычка одноразовая."}
