MultiLanguageSpellData['ru'][1265793] = {name = "Указ Бездны", additional_info = "Неограниченное расстояние\nМгновенное действие\n[q]Бело'рен яростно атакует цели в секторе перед собой, нанося 2415233 ед. урона от темной магии и 966093 ед. физического урона, а также отбрасывая их."}
MultiLanguageSpellData['ru'][1265794] = {name = "Неумолимые удары", additional_info = "Радиус действия: 8 м\nМгновенное действие\n[q]Применив \"Погибель королей\", вы быстро атакуете ту же цель 5 раза:раз в течение 1 сек., нанося ([300% of Attack Power]) ед. физического урона и ([207% of Attack Power]) ед. урона от сил природы. Каждый удар применяет к противнику смертельные яды на оружии и дает один прием серии."}
MultiLanguageSpellData['ru'][1265795] = {name = "Неумолимые удары", additional_info = "Радиус действия: 8 м\nМгновенное действие\n[q]Применив \"Погибель королей\", вы быстро атакуете ту же цель 5 раза:раз в течение 1 сек., нанося ([300% of Attack Power]) ед. физического урона и ([207% of Attack Power]) ед. урона от сил природы. Каждый удар применяет к противнику смертельные яды на оружии и дает один прием серии."}
MultiLanguageSpellData['ru'][1265797] = {name = "Curse of Exhaustion [NYI]", additional_info = "[q]Во время действия заменяет \"Проклятие слабости\".\n\n Снижает скорость передвижения цели на 50% на 12 сек.\n\nПроклятие: на каждую цель чернокнижника может воздействовать только одно его проклятие или бедствие единовременно."}
MultiLanguageSpellData['ru'][1265799] = {name = "Бедствие слабости", additional_info = "[q]Призывает облако опьяняющего тумана тьмы, которое окутывает цель и других противников в радиусе 10 м, увеличивая интервал между их атаками на 100% и снижая вероятность критического удара на 10% на 12 сек.\n\nПроклятие: на каждую цель чернокнижника может воздействовать только одно его проклятие или бедствие единовременно."}
