MultiLanguageSpellData['ru'][1265855] = {name = "Отголосок ярости", additional_info = "[q]Лед\n Метка жнеца\" наносит на 5% больше урона.\n\n Применение \"Метки жнеца\" дает 1 эффект \"Истребления\" с 100% эффективности первой косы и 100% эффективности второй косы.\n\nКровь\n Метка жнеца\" наносит на 5% больше урона.\n\n Применение \"Танцующего рунического оружия\" дает 1 эффект \"Истребления\" с 100% эффективности первой косы и 100% эффективности второй косы."}
MultiLanguageSpellData['ru'][1265857] = {name = "Наслаждение болью", additional_info = "Мгновенное действие\n[q]6.0% вашего урона от огня превращается в щит, поглощающий до (Всего очков здоровья * 10 / 100) ед. урона.\n\n Во время действия \"Огненного клейма\" процент преобразования и максимальный запас прочности увеличиваются вдвое."}
MultiLanguageSpellData['ru'][1265859] = {name = "Леденящая решимость", additional_info = "[q]Кровь\n \"Мерзлотность\" усиливается на 100%, а \"Истребление\" дает эффект \"Мерзлотности\" в размере 10% нанесенного урона.\n\nМерзлотность\nУрон от автоатак дает щит, поглощающий 50% от нанесенного ими урона.\n\nЛед\n \"Мерзлотность\" усиливается на 50%.\n\nМерзлотность\nУрон от автоатак дает щит, поглощающий 50% от нанесенного ими урона."}
MultiLanguageSpellData['ru'][1265860] = {name = "Леденящий голод", additional_info = "Мгновенное действие\n[q]Кровь\n\"Мерзлотность\" усиливается на 100%, а \"Истребление\" дает эффект \"Мерзлотности\" в размере 10% нанесенного урона.\n\nМерзлотность\nУрон от автоатак дает щит, поглощающий 50% от нанесенного ими урона.\n\nЛед\n\"Мерзлотность\" усиливается на 50%.\n\nМерзлотность\nУрон от автоатак дает щит, поглощающий 50% от нанесенного ими урона."}
