MultiLanguageSpellData['ru'][1279596] = {name = "Руна меченных Бездной сфер", additional_info = "[q0]Фолиант омниума\n[q]Основная руна\n\n Раз в 10 сек. вы накапливаете одну меченную Бездной сферу. Максимум – 5сферы:сфер.\n\n Когда вы наносите урон противнику, вы выпускаете в него все накопленные сферы, каждая из которых наносит [(((1 / 100 * 281 ))) * 977] ед. космического урона.\n\n Когда вы применяете исцеляющее заклинание, вы выпускаете сферы в находящегося рядом союзника с самым низким уровнем здоровья. Каждая сфера восполняет цели [(((1 / 100 * 281 ))) * 2051] ед. здоровья."}
MultiLanguageSpellData['ru'][1279599] = {name = "Руна высвобожденного пламени", additional_info = "[q0]Фолиант омниума\nСрабатывает приблизительно 9 раз(а) в минуту\n[q]Основная руна\n\n Заклинания и способности с высокой вероятностью обрушивают на цель силу пламени, нанося противнику [(((1 / 100 * 281 ))) * 977] ед. урона от огня или восстанавливая [(((1 / 100 * 281 ))) * 2051] ед. здоровья находящемуся рядом союзнику с самым низким уровнем здоровья."}
MultiLanguageSpellData['ru'][1279603] = {name = "Руна самоисцеления", additional_info = "[q0]Фолиант омниума\n[q]Когда ваша основная руна ( Меченные Бездной сферы ) наносит урон или исцеляет цель, вы восполняете [(((1 / 100 * 281 ))) * 2051] ед. здоровья, если ваш уровень здоровья ниже 75%."}
MultiLanguageSpellData['ru'][1279604] = {name = "Руна оскверненной Бездной оболочки", additional_info = "[q0]Фолиант омниума\n[q]Когда вы теряете более 10% максимального запаса здоровья от одной атаки, вы на 10 сек. получаете щит, поглощающий [(((1 / 100 * 281 ))) * 6592] ед. урона, но наносящий вам [(((1 / 100 * 281 ))) * 3296] ед. урона за 10 сек.\n\n Эффект срабатывает не чаще раза в 30 сек.\n(Восстановление: 30с)"}
